package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.paiflow.domain.ModelOperationRecord;
import com.ruoyi.paiflow.mapper.ModelOperationMapper;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.paiflow.service.ModelOperationJson.*;
import static com.ruoyi.paiflow.service.ModelOperationPorts.*;

/** 只读批准边界：目录/Profile/账本隔离夹具；不派发 Provider，也不把许可当业务验收。 */
class ManagedJavaModelInvocationPolicyTest {
    @Test void originalLiteralNumericAndNestedMessagesStayEqualAcrossVerifiedSnapshot() throws Exception {
        try(var in=getClass().getResourceAsStream("/fixtures/java-model/original-literal-golden.json")){assertNotNull(in);var samples=JSON.parseArray(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));assertEquals(14,samples.size());
            for(Object raw:samples){var sample=(JSONObject)raw;var n=ModelMessageSources.sourceObject(sample.getString("nodeJson"));var params=n.getJSONObject("data").getJSONObject("nodeParam");params.put("modelId",1);params.put("source","openai");params.put("domain","fixture-model");params.put("modelResourceId",RESOURCE);
                Object content=n.getJSONObject("data").getJSONArray("inputs").getJSONObject(0).getJSONObject("schema").getJSONObject("value").get("content");var actual=JavaToolSemantics.inputs(n,Map.of("node-start::s",JavaToolSemantics.startPool(JSONObject.of("q",content))));var f=new Fixture();var p=f.request(n,new JSONObject(actual));p.getJSONArray("messages").getJSONObject(0).put("content",sample.get("rendered"));
                // 固定节点和可信快照均使用中心真实规范序列化，不能混用未排序画布与已排序引用。
                var c=f.call(n,new JSONObject(actual),p);
                var candidate=c;assertNotNull(assertDoesNotThrow(()->f.policy.approveCall(candidate),sample.getString("rawLiteral")));
            }
        }
    }
    static final String RESOURCE="model:1:version:2";
    static JSONObject node(Integer max,Integer n){
        var p=JSONObject.of("modelId",1,"source","openai","domain","fixture-model","modelResourceId",RESOURCE,"template","答：{{q}}","systemTemplate","固定说明","maxTokens",max);
        if(n!=null)p.put("extraParams",JSONObject.of("n",n));
        var input=JSONObject.of("name","q","schema",JSONObject.of("value",JSONObject.of("type","ref","content",JSONObject.of("nodeId","start::s","name","q"))));
        return JSONObject.of("id","spark-llm::m","data",JSONObject.of("inputs",JSONArray.of(input),"nodeParam",p));
    }
    static final class Fixture {
        final ManagedModelRuntime runtime=mock(ManagedModelRuntime.class);
        final ModelRuntimeCatalog catalog=mock(ModelRuntimeCatalog.class);
        final ModelOperationMapper operations=mock(ModelOperationMapper.class);
        final ModelRuntimeProperties.Profile profile=new ModelRuntimeProperties.Profile();
        final ManagedModelInvocationPolicy policy=new ManagedModelInvocationPolicy(runtime,catalog,operations);
        Fixture(){profile.setInvocationAllowed(true);profile.setRuntimeProvider("openai");profile.setSourceProvider("openai-compatible");profile.setDomain("fixture-model");profile.setEndpoint("https://provider.invalid/v1/chat/completions");profile.setCredentialRef("fixture-reference");profile.setMaxCalls(3);profile.setMaxTokens(10000);profile.setMaxRequestBytes(65536);profile.setTimeoutSeconds(5);profile.setAllowedUserIds(List.of(42L));profile.setAllowedSpaceIds(List.of(7L));
            var fixed=mock(ModelRuntimeCatalog.FixedModel.class);when(catalog.resolvePinned(eq(7L),eq(42L),eq(RESOURCE),any())).thenReturn(fixed);when(runtime.profile(fixed)).thenReturn(profile);when(operations.forRunResource("run",RESOURCE)).thenReturn(List.of());}
        JSONObject request(JSONObject node,JSONObject values){return JSONObject.of("resourceId",RESOURCE,"resourceVersion","2","provider","openai","modelName","fixture-model","mode","chat","messages",JavaModelSemantics.messages(node,values,new JSONArray()),"options",JavaModelSemantics.options(node));}
        CallCandidate call(JSONObject node,JSONObject values,JSONObject request){String raw=canonical(request,REQUEST_BYTES);return new CallCandidate("run","lease",1,42,7,9,"a".repeat(64),"spark-llm::m",null,RESOURCE,"2","openai",raw,sha(raw),"{\"q\":\"伪根输入\"}",canonical(node,REQUEST_BYTES),"[]","model-run:fixture",Instant.now().plusSeconds(60),"[]",canonical(values,REQUEST_BYTES),"java","fixture-fingerprint");}
        RunCandidate run(JSONObject node){return new RunCandidate("run",42,7,9,"a".repeat(64),"{}",canonical(JSONObject.of(RESOURCE,JSONObject.of("kind","model")),REQUEST_BYTES),canonical(JSONObject.of("nodes",JSONArray.of(node)),REQUEST_BYTES),Instant.now().plusSeconds(60),"java","run-fingerprint");}
    }
    @Test void originalEightNullableOptionsAndTwoChoicesUseTrustedJavaMessages(){var f=new Fixture();f.profile.setProviderDefaultMaxTokens(128);var node=node(null,2);var values=JSONObject.of("q","实际已核输入");var request=f.request(node,values);assertNotNull(f.policy.approveCall(f.call(node,values,request)));assertNull(request.getJSONObject("options").get("maxTokens"));assertEquals(8,request.getJSONObject("options").size());assertEquals("答：实际已核输入",request.getJSONArray("messages").getJSONObject(1).getString("content"));}
    @Test void nullableWithoutCertifiedProviderMaximumRejectsRunBeforeDispatch(){var f=new Fixture();assertEquals(503,assertThrows(ServiceException.class,()->f.policy.approveRun(f.run(node(null,null)))).getCode());verifyNoInteractions(f.operations);}
    @Test void explicitMaximumCanAdmitRunWithoutDefault(){var f=new Fixture();assertNotNull(f.policy.approveRun(f.run(node(256,2))));verifyNoInteractions(f.operations);}
    @Test void nullableDefaultChangeRevokesPreviouslyApprovedRun(){var f=new Fixture();f.profile.setProviderDefaultMaxTokens(128);var c=f.run(node(null,2));var permit=f.policy.approveRun(c);assertTrue(f.policy.currentRun(c,permit));f.profile.setProviderDefaultMaxTokens(129);assertFalse(f.policy.currentRun(c,permit));}
    @Test void tamperedMessagesMissingVerifiedSnapshotAndWrongEngineAreRejected(){var f=new Fixture();var n=node(256,null);var values=JSONObject.of("q","中心原值");var p=f.request(n,values);p.getJSONArray("messages").getJSONObject(1).put("content","Worker替换");assertThrows(ServiceException.class,()->f.policy.approveCall(f.call(n,values,p)));var original=f.call(n,values,f.request(n,values));for(String engine:List.of("java","unknown","python")){var c=new CallCandidate(original.runId(),original.leaseId(),original.attempt(),42,7,9,original.dslHash(),original.nodeId(),null,RESOURCE,"2","openai",original.parametersJson(),original.parametersHash(),original.inputJson(),original.nodeJson(),"[]",original.runApprovalRef(),original.deadline(),"[]",engine.equals("java")?null:original.verifiedInputsJson(),engine,original.fingerprint());assertThrows(ServiceException.class,()->f.policy.approveCall(c));}verifyNoInteractions(f.operations);}
    @Test void exhaustedOutputAcrossMultipleChoicesCannotBorrowPythonSingleChoiceBudget(){var f=new Fixture();var n=node(1000,2);var v=JSONObject.of("q","原值");var p=f.request(n,v);var row=new ModelOperationRecord();row.setParametersJson(canonical(p,REQUEST_BYTES));row.setApprovalJson(canonical(JSONObject.of("candidate",JSONObject.of("engineProfile","java")),REQUEST_BYTES));when(f.operations.forRunResource("run",RESOURCE)).thenReturn(List.of(row));f.profile.setMaxTokens(3500);assertEquals(429,assertThrows(ServiceException.class,()->f.policy.approveCall(f.call(n,v,p))).getCode());}
    @Test void zeroAndNegativeOriginalWireValuesNeverPretendToHaveOutputBound(){for(int max:List.of(0,-1)){var f=new Fixture();var n=node(max,null);assertEquals(max,JavaModelSemantics.options(n).getInteger("maxTokens"));assertThrows(ServiceException.class,()->f.policy.approveRun(f.run(n)));}}
    @Test void privateRunEngineCannotReusePythonPermitEvenWithSameProvidedFingerprint(){var f=new Fixture();var c=f.run(node(256,null));var old=new RunCandidate(c.runId(),42,7,9,c.dslHash(),c.inputJson(),c.resourcesJson(),c.executionJson(),c.deadline(),c.fingerprint());assertFalse(f.policy.currentRun(c,f.policy.approveRun(old)));}
    @Test void defaultBudgetIsExplicitPositiveProfileFactAndDoesNotLimitExplicitSmallerCall(){var f=new Fixture();var properties=new ModelRuntimeProperties();var p=f.profile;p.setEnabled(true);p.setSecretAlias("ai.fixture");p.setSecretProvider("fixture");p.setCapability("chat");p.setAuthMode("bearer");properties.setProfiles(List.of(p));var actual=new ManagedModelRuntime(properties,mock(com.ruoyi.system.secret.ManagedSecretService.class));assertNull(p.getProviderDefaultMaxTokens());assertSame(p,actual.profile(p.getSourceProvider(),p.getDomain(),p.getEndpoint(),p.getCredentialRef()));p.setProviderDefaultMaxTokens(0);assertEquals(503,assertThrows(ServiceException.class,()->actual.profile(p.getSourceProvider(),p.getDomain(),p.getEndpoint(),p.getCredentialRef())).getCode());p.setProviderDefaultMaxTokens(Integer.MAX_VALUE);assertEquals(429,assertThrows(ServiceException.class,()->f.policy.approveRun(f.run(node(null,2)))).getCode());assertNotNull(f.policy.approveRun(f.run(node(256,2))));}
    @Test void fixedLiteralMapIsJacksonPlainButReferencedMapKeepsVariablePoolContainer(){var f=new Fixture();var n=node(256,null);var fields=n.getJSONObject("data").getJSONArray("inputs");var literal=JSONObject.of("z",1,"a",false);fields.add(JSONObject.of("name","literal","schema",JSONObject.of("value",JSONObject.of("type","literal","content",literal))));n.getJSONObject("data").getJSONObject("nodeParam").put("template","{{q}}/{{literal}}");var v=JSONObject.of("q",JSONObject.of("a",false,"z",1),"literal",literal);var sortedNode=ModelMessageSources.sourceObject(canonical(n,REQUEST_BYTES));var expectedInputs=new LinkedHashMap<String,Object>();expectedInputs.put("q",ModelMessageSources.sourceObject(canonical(v.get("q"),REQUEST_BYTES)));expectedInputs.put("literal",new LinkedHashMap<String,Object>(sortedNode.getJSONObject("data").getJSONArray("inputs").getJSONObject(1).getJSONObject("schema").getJSONObject("value").getJSONObject("content")));var p=f.request(n,v);p.put("messages",JavaModelSemantics.messages(sortedNode,expectedInputs,new JSONArray()));assertTrue(p.getJSONArray("messages").getJSONObject(1).getString("content").contains("{a=false, z=1}"));assertNotNull(f.policy.approveCall(f.call(n,v,p)));v.getJSONObject("literal").put("a",true);assertThrows(ServiceException.class,()->f.policy.approveCall(f.call(n,v,p)));}
    @Test void fiveRealOriginalSdkRequestGoldensAreAcceptedWithoutWireDefaults() throws Exception {try(var stream=getClass().getResourceAsStream("/fixtures/java-model/original-java-model-wire-golden.json")){assertNotNull(stream);var samples=JSON.parseArray(new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));assertEquals(5,samples.size());for(Object raw:samples){var s=(JSONObject)raw;int variant=s.getIntValue("variant");var f=new Fixture();f.profile.setProviderDefaultMaxTokens(128);var n=node(variant==0?null:32,null);n.getJSONObject("data").put("inputs",new JSONArray());var params=n.getJSONObject("data").getJSONObject("nodeParam");params.put("template","问题");params.put("systemTemplate","系统");if(variant==1)params.put("extraParams",JSONObject.of("maxTokens",12,"temperature",0,"topP",0.0,"presencePenalty",0,"frequencyPenalty",0,"n",1));if(variant==2)params.put("extraParams",JSONObject.of("maxTokens","bad","temperature","bad","topP","bad","n","bad"));if(variant==3)params.put("extraParams",JSONObject.of("n",2));var p=JSON.parseObject(s.getJSONObject("actualRequest").getJSONObject("parameters").toJSONString(JSONWriter.Feature.WriteMapNullValue));p.put("resourceId",RESOURCE);p.put("resourceVersion","2");assertNotNull(f.policy.approveCall(f.call(n,new JSONObject(),p)),"实际 variant "+variant);}}}
    @Test void callCountRequestBytesAndUnboundPriorJavaLedgerRejectWithoutDispatch(){var f=new Fixture();var n=node(256,null);var v=JSONObject.of("q","实际值");var p=f.request(n,v);var row=new ModelOperationRecord();row.setParametersJson(canonical(p,REQUEST_BYTES));when(f.operations.forRunResource("run",RESOURCE)).thenReturn(List.of(row));assertEquals(403,assertThrows(ServiceException.class,()->f.policy.approveCall(f.call(n,v,p))).getCode());f.profile.setMaxCalls(1);assertEquals(429,assertThrows(ServiceException.class,()->f.policy.approveCall(f.call(n,v,p))).getCode());f.profile.setMaxRequestBytes(1);assertEquals(403,assertThrows(ServiceException.class,()->f.policy.approveCall(f.call(n,v,p))).getCode());}
    @Test void oldConstructorsAndPythonRunHashKeepTheirOriginalFacts(){var f=new Fixture();var javaCandidate=f.run(node(256,null));var old=new RunCandidate(javaCandidate.runId(),42,7,9,javaCandidate.dslHash(),javaCandidate.inputJson(),javaCandidate.resourcesJson(),javaCandidate.executionJson(),javaCandidate.deadline(),javaCandidate.fingerprint());assertEquals("python",old.engineProfile());var permit=f.policy.approveRun(old);assertTrue(f.policy.currentRun(old,permit));var options=ModelOperationOptions.fromNode(JSONObject.of("modelId",1,"source","openai","domain","fixture-model"));var p=JSONObject.of("options",options);assertEquals(2048,ManagedModelInvocationPolicy.reservedTokens(options));assertEquals(2048+canonical(p,REQUEST_BYTES).getBytes(java.nio.charset.StandardCharsets.UTF_8).length,ManagedModelInvocationPolicy.reservation(p));var c=f.call(node(256,null),JSONObject.of("q","x"),f.request(node(256,null),JSONObject.of("q","x")));var oldCall=new CallCandidate(c.runId(),c.leaseId(),1,42,7,9,c.dslHash(),c.nodeId(),null,RESOURCE,"2","openai",c.parametersJson(),c.parametersHash(),c.inputJson(),c.nodeJson(),"[]",c.runApprovalRef(),c.deadline(),"[]",c.verifiedInputsJson(),c.fingerprint());assertEquals("python",oldCall.engineProfile());f.profile.setProviderDefaultMaxTokens(128);assertFalse(f.policy.currentRun(old,permit));}
}

